// ---- scripted RNG (replaces Random.cpp) -------------------------------------
static std::deque<uint32> g_urand;     // values returned by urand/irand, in order
static std::deque<uint32> g_words;     // engine words returned by rand32
static std::vector<std::string> g_log; // "urand(lo,hi)=v" / "rand32=v"

uint32 urand(uint32 min, uint32 max)
{
    if (g_urand.empty())
        throw std::runtime_error("urand: script exhausted");
    uint32 v = g_urand.front();
    g_urand.pop_front();
    if (v < min || v > max)
        throw std::runtime_error("urand: scripted value out of range");
    g_log.push_back("urand(" + std::to_string(min) + "," + std::to_string(max) + ")=" + std::to_string(v));
    return v;
}
int32 irand(int32 min, int32 max) { return int32(urand(uint32(min), uint32(max))); }
uint32 rand32()
{
    if (g_words.empty())
        throw std::runtime_error("rand32: script exhausted");
    uint32 v = g_words.front();
    g_words.pop_front();
    g_log.push_back("rand32=" + std::to_string(v));
    return v;
}
uint32 urandms(uint32, uint32) { throw std::runtime_error("unused"); }
float frand(float, float) { throw std::runtime_error("unused"); }
float rand_norm() { throw std::runtime_error("unused"); }
float rand_chance() { throw std::runtime_error("unused"); }
uint32 urandweighted(size_t, double const*) { throw std::runtime_error("unused"); }
Milliseconds randtime(Milliseconds, Milliseconds) { throw std::runtime_error("unused"); }


